from pysat.solvers import Glucose3
from pysat.card import *

# 5x5 board, cells 0-24
N = 5
NUM_CELLS = N * N  # 25

# Build knight move adjacency
def get_knight_moves(cell):
    r, c = cell // N, cell % N
    moves = []
    for dr, dc in [(-2,-1),(-2,1),(-1,-2),(-1,2),(1,-2),(1,2),(2,-1),(2,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < N and 0 <= nc < N:
            moves.append(nr * N + nc)
    return moves

adj = {i: get_knight_moves(i) for i in range(NUM_CELLS)}

# Variables: x[t][c] = 1 means at time t we visit cell c
# t in 0..24, c in 0..24
# We'll use variable encoding: var(t, c) = t * 25 + c + 1 (1-indexed for SAT)

def var(t, c):
    return t * NUM_CELLS + c + 1

solver = Glucose3()

# Constraint: at each time step, exactly one cell is visited
for t in range(NUM_CELLS):
    # At least one cell
    solver.add_clause([var(t, c) for c in range(NUM_CELLS)])
    # At most one cell (pairwise)
    for c1 in range(NUM_CELLS):
        for c2 in range(c1+1, NUM_CELLS):
            solver.add_clause([-var(t, c1), -var(t, c2)])

# Constraint: each cell is visited exactly once
for c in range(NUM_CELLS):
    # At least one time
    solver.add_clause([var(t, c) for t in range(NUM_CELLS)])
    # At most one time
    for t1 in range(NUM_CELLS):
        for t2 in range(t1+1, NUM_CELLS):
            solver.add_clause([-var(t1, c), -var(t2, c)])

# Constraint: consecutive time steps must be knight moves
for t in range(NUM_CELLS - 1):
    for c in range(NUM_CELLS):
        # If at time t we're at cell c, then at time t+1 we must be at a knight move from c
        # var(t, c) => OR_{c' in adj[c]} var(t+1, c')
        # Equivalent to: -var(t, c) OR var(t+1, c1) OR var(t+1, c2) OR ...
        clause = [-var(t, c)] + [var(t+1, c2) for c2 in adj[c]]
        solver.add_clause(clause)

# Fixed assignments
fixed = {3: 23, 4: 16, 5: 5, 15: 15, 22: 24}
for t, c in fixed.items():
    solver.add_clause([var(t, c)])
    # Also fix that at time t, no other cell is visited
    for c2 in range(NUM_CELLS):
        if c2 != c:
            solver.add_clause([-var(t, c2)])
    # Also fix that cell c is not visited at any other time
    for t2 in range(NUM_CELLS):
        if t2 != t:
            solver.add_clause([-var(t2, c)])

# Start at cell 0
solver.add_clause([var(0, 0)])
for c in range(1, NUM_CELLS):
    solver.add_clause([-var(0, c)])
for t in range(1, NUM_CELLS):
    solver.add_clause([-var(t, 0)])

print("Solving...")
if solver.solve():
    model = solver.get_model()
    # Extract solution
    solution = [0] * NUM_CELLS
    for t in range(NUM_CELLS):
        for c in range(NUM_CELLS):
            if var(t, c) in model:
                solution[t] = c
                break
    print("Solution found:", solution)

    # Verify
    for t in range(NUM_CELLS - 1):
        c1, c2 = solution[t], solution[t+1]
        r1, c1_col = c1 // N, c1 % N
        r2, c2_col = c2 // N, c2 % N
        dr, dc = abs(r1 - r2), abs(c1_col - c2_col)
        assert (dr == 1 and dc == 2) or (dr == 2 and dc == 1), f"Invalid move at step {t}: {c1} -> {c2}"

    assert len(set(solution)) == NUM_CELLS, "Not all cells visited"
    assert solution[0] == 0, "Doesn't start at 0"
    for t, c in fixed.items():
        assert solution[t] == c, f"Fixed assignment violated at t={t}"

    print("Solution verified!")
else:
    print("UNSATISFIABLE")
